PAYLOAD = r'''{"title":"YOU ARE NOT A THING","slug":"pattern-wearing-matter-v2","user_vo":true,"external_audio_finalization":true,"external_audio_duration":185.730563,"external_audio_sha256":"40cf81e45fa4dba595be5fcf56ca3114cadf31be14444c4566e1c5a987eecc4d","voice_standard":"Liam energetic social media creator; exact supplied waveform required for final delivery","layout":"fullbleed","visual_policy":{"mode":"diverse_symbols","max_human_ratio":0.35,"max_family_run":2,"min_families":8},"accent_color":"cool cyan","max_still_source_ratio":0.0,"music_variant_count":3,"scenes":[{"text":"What if you are not a thing? I know. That is a rude way to start a conversation.","keywords":["not a thing"],"kw_times":{"not a thing":1.49},"semantic_anchor":"A human-shaped pattern continually rebuilds itself from moving luminous particles; the outline stays while its material changes.","visual_function":"perspective_shift","symbol_family":"identity","primary_symbol":"identity flow","query":"A human-shaped pattern continually rebuilds itself from moving luminous particles; the outline stays while its material changes.","symbol_query":"A human-shaped pattern continually rebuilds itself from moving luminous particles; the outline stays while its material changes.","symbolic_kind":"identity_flow","symbolic_palette":"cyan","start":0.0,"duration":9.017,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"You woke up, paid bills, found your keys after accusing everybody in the house of moving them… and now somebody is telling you that you might not even be an object.","keywords":["paid bills","found your keys"],"kw_times":{"paid bills":10.196,"found your keys":11.04},"semantic_anchor":"Household bills and keys surround an OBJECT? label, grounding the joke that an ordinary person is being classified as a thing.","visual_function":"contrast","symbol_family":"object_tool","primary_symbol":"keys bills object","query":"Household bills and keys surround an OBJECT? label, grounding the joke that an ordinary person is being classified as a thing.","symbol_query":"Household bills and keys surround an OBJECT? label, grounding the joke that an ordinary person is being classified as a thing.","symbolic_kind":"keys_bills_object","symbolic_palette":"amber","start":9.017,"duration":11.885,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"But look closer. A whirlpool is not made of specific water.","keywords":["whirlpool","specific water"],"kw_times":{"whirlpool":22.338,"specific water":23.681},"semantic_anchor":"A clear particle whirlpool forms while new particles enter and old particles leave, directly showing that the vortex is not specific material.","visual_function":"mechanism","symbol_family":"nature","primary_symbol":"whirlpool material","query":"A clear particle whirlpool forms while new particles enter and old particles leave, directly showing that the vortex is not specific material.","symbol_query":"A clear particle whirlpool forms while new particles enter and old particles leave, directly showing that the vortex is not specific material.","symbolic_kind":"whirlpool_material","symbolic_palette":"cyan","start":20.902,"duration":4.552,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"The water keeps leaving. New water keeps entering. Yet somehow, the whirlpool remains.","keywords":["water keeps leaving","whirlpool remains"],"kw_times":{"water keeps leaving":25.454,"whirlpool remains":28.999},"semantic_anchor":"Different particles continuously replace one another while the same whirlpool shape persists.","visual_function":"recursion","symbol_family":"transformation","primary_symbol":"whirlpool persistence","query":"Different particles continuously replace one another while the same whirlpool shape persists.","symbol_query":"Different particles continuously replace one another while the same whirlpool shape persists.","symbolic_kind":"whirlpool_persistence","symbolic_palette":"blue","start":25.454,"duration":5.653,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"So what exactly is the whirlpool? Not the water. The relationship between movement, pressure, gravity, and shape. It is a pattern wearing water for a little while.","keywords":["movement","pressure","gravity","shape"],"kw_times":{"movement":35.183,"pressure":36.698,"gravity":37.479,"shape":38.26},"semantic_anchor":"The whirlpool remains at center while labeled vectors MOVEMENT, PRESSURE, GRAVITY, and SHAPE define the relationship that creates it.","visual_function":"mechanism","symbol_family":"geometry","primary_symbol":"forces pattern","query":"The whirlpool remains at center while labeled vectors MOVEMENT, PRESSURE, GRAVITY, and SHAPE define the relationship that creates it.","symbol_query":"The whirlpool remains at center while labeled vectors MOVEMENT, PRESSURE, GRAVITY, and SHAPE define the relationship that creates it.","symbolic_kind":"forces_pattern","symbolic_palette":"violet","start":31.107,"duration":12.041,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"And maybe you are doing the same thing. Your body has changed. Your thoughts have changed. Your beliefs have changed.","keywords":["body","thoughts","beliefs"],"kw_times":{"body":46.263,"thoughts":48.036,"beliefs":49.808},"semantic_anchor":"A human silhouette remains while BODY, THOUGHTS, and BELIEFS visibly shift and change inside it.","visual_function":"transformation","symbol_family":"identity","primary_symbol":"self change","query":"A human silhouette remains while BODY, THOUGHTS, and BELIEFS visibly shift and change inside it.","symbol_query":"A human silhouette remains while BODY, THOUGHTS, and BELIEFS visibly shift and change inside it.","symbolic_kind":"self_change","symbolic_palette":"green","start":43.148,"duration":8.433,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"You have lost cells, gained memories, forgotten passwords, changed opinions, and probably become deeply offended by something you once agreed with.","keywords":["lost cells","memories","passwords","opinions"],"kw_times":{"lost cells":51.581,"memories":53.096,"passwords":53.939,"opinions":54.782},"semantic_anchor":"Cards labeled CELLS, MEMORIES, PASSWORDS, and OPINIONS keep changing beneath one fixed ME label.","visual_function":"contrast","symbol_family":"time_memory","primary_symbol":"memory tiles","query":"Cards labeled CELLS, MEMORIES, PASSWORDS, and OPINIONS keep changing beneath one fixed ME label.","symbol_query":"Cards labeled CELLS, MEMORIES, PASSWORDS, and OPINIONS keep changing beneath one fixed ME label.","symbolic_kind":"memory_tiles","symbolic_palette":"amber","start":51.581,"duration":8.167,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"Yet you still call all of it “me.” But what stayed? Not the material. Not the mood. Not even the story. What stayed was the relationship between the pieces.","keywords":["me","relationship"],"kw_times":{"me":61.091,"relationship":70.055},"semantic_anchor":"The pieces repeatedly change shape and position while the connecting relationships remain intact.","visual_function":"recursion","symbol_family":"geometry","primary_symbol":"relationship pieces","query":"The pieces repeatedly change shape and position while the connecting relationships remain intact.","symbol_query":"The pieces repeatedly change shape and position while the connecting relationships remain intact.","symbolic_kind":"relationship_pieces","symbolic_palette":"cyan","start":59.748,"duration":12.08,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"You may not be a solid person moving through time. You may be an arrangement that keeps rebuilding the idea of a person.","keywords":["solid person","rebuilding"],"kw_times":{"solid person":73.507,"rebuilding":77.965},"semantic_anchor":"Scattered pieces repeatedly assemble into a person-shaped arrangement, then begin rebuilding again.","visual_function":"transformation","symbol_family":"identity","primary_symbol":"self rebuild","query":"Scattered pieces repeatedly assemble into a person-shaped arrangement, then begin rebuilding again.","symbol_query":"Scattered pieces repeatedly assemble into a person-shaped arrangement, then begin rebuilding again.","symbolic_kind":"self_rebuild","symbolic_palette":"violet","start":71.828,"duration":8.581,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"Like a song. A song is not the piano. It is not the speaker. It is not even the air vibrating in the room.","keywords":["song","speaker","air"],"kw_times":{"song":81.846,"speaker":84.29,"air":88.077},"semantic_anchor":"A piano and speaker fade away while the waveform of the song continues across the frame.","visual_function":"contrast","symbol_family":"language","primary_symbol":"song not object","query":"A piano and speaker fade away while the waveform of the song continues across the frame.","symbol_query":"A piano and speaker fade away while the waveform of the song continues across the frame.","symbolic_kind":"song_not_object","symbolic_palette":"blue","start":80.409,"duration":9.776,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"Destroy the piano, and the song can still be played somewhere else. Because the song was never trapped inside the instrument. The instrument was just one place the relationship became audible.","keywords":["Destroy the piano","instrument","audible"],"kw_times":{"Destroy the piano":90.185,"instrument":96.495,"audible":99.946},"semantic_anchor":"One continuous waveform travels from piano to air to speaker, showing the song can be played through different instruments.","visual_function":"transformation","symbol_family":"object_tool","primary_symbol":"song transfer","query":"One continuous waveform travels from piano to air to speaker, showing the song can be played through different instruments.","symbol_query":"One continuous waveform travels from piano to air to speaker, showing the song can be played through different instruments.","symbolic_kind":"song_transfer","symbolic_palette":"cyan","start":90.185,"duration":11.869,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"That raises an uncomfortable question. What if your body is not producing you? What if your body is where your pattern is currently being played?","keywords":["producing you","pattern"],"kw_times":{"producing you":105.506,"pattern":109.488},"semantic_anchor":"A waveform passes through a resonant human silhouette as if the body is where the pattern is currently being played.","visual_function":"mechanism","symbol_family":"identity","primary_symbol":"body receiver","query":"A waveform passes through a resonant human silhouette as if the body is where the pattern is currently being played.","symbol_query":"A waveform passes through a resonant human silhouette as if the body is where the pattern is currently being played.","symbolic_kind":"body_receiver","symbolic_palette":"green","start":102.054,"duration":10.073,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"Now, before you start floating away from your taxes, calm down. This does not mean you are secretly a Wi-Fi signal from another dimension.","keywords":["taxes","Wi-Fi signal"],"kw_times":{"taxes":114.251,"Wi-Fi signal":119.217},"semantic_anchor":"A Wi-Fi router broadcasts over a stack of tax papers, making the dimensional-signal joke visually literal.","visual_function":"contrast","symbol_family":"object_tool","primary_symbol":"wifi taxes","query":"A Wi-Fi router broadcasts over a stack of tax papers, making the dimensional-signal joke visually literal.","symbol_query":"A Wi-Fi router broadcasts over a stack of tax papers, making the dimensional-signal joke visually literal.","symbolic_kind":"wifi_taxes","symbolic_palette":"amber","start":112.127,"duration":9.534,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"Though, honestly, some of us do lose connection every time we walk into the kitchen and forget why we went in there.","keywords":["kitchen","forget why"],"kw_times":{"kitchen":125.573,"forget why":127.923},"semantic_anchor":"A person icon confidently enters a labeled kitchen, then the thought bubble turns into an empty ellipsis.","visual_function":"contrast","symbol_family":"architecture","primary_symbol":"kitchen forget","query":"A person icon confidently enters a labeled kitchen, then the thought bubble turns into an empty ellipsis.","symbol_query":"A person icon confidently enters a labeled kitchen, then the thought bubble turns into an empty ellipsis.","symbolic_kind":"kitchen_forget","symbolic_palette":"cyan","start":121.661,"duration":8.706,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"But consider this. A family is not a collection of bodies. It is a pattern of memories, tensions, jokes, loyalties, expectations, and one person who refuses to admit they started the argument.","keywords":["memories","jokes","loyalties","argument"],"kw_times":{"memories":134.92,"jokes":137.887,"loyalties":138.668,"argument":142.244},"semantic_anchor":"Family nodes are connected by MEMORIES, TENSIONS, JOKES, LOYALTIES, EXPECTATIONS, and one evasive ARGUMENT node.","visual_function":"recursion","symbol_family":"collective","primary_symbol":"family network","query":"Family nodes are connected by MEMORIES, TENSIONS, JOKES, LOYALTIES, EXPECTATIONS, and one evasive ARGUMENT node.","symbol_query":"Family nodes are connected by MEMORIES, TENSIONS, JOKES, LOYALTIES, EXPECTATIONS, and one evasive ARGUMENT node.","symbolic_kind":"family_network","symbolic_palette":"violet","start":130.367,"duration":13.985,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"A city is not its buildings. Replace every brick slowly enough, and people still call it the same city.","keywords":["city","every brick","same city"],"kw_times":{"city":144.352,"every brick":146.796,"same city":149.99},"semantic_anchor":"Every brick in a city skyline changes one by one while the city outline and identity remain.","visual_function":"transformation","symbol_family":"architecture","primary_symbol":"city bricks","query":"Every brick in a city skyline changes one by one while the city outline and identity remain.","symbol_query":"Every brick in a city skyline changes one by one while the city outline and identity remain.","symbolic_kind":"city_bricks","symbolic_palette":"blue","start":144.352,"duration":7.41,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"A flame is not the wood. The wood disappears. The flame continues. Reality may preserve processes more faithfully than it preserves objects.","keywords":["flame","wood disappears","processes"],"kw_times":{"flame":151.762,"wood disappears":154.206,"processes":158.759},"semantic_anchor":"Wood visibly shrinks and disappears while the flame continues burning as the persistent process.","visual_function":"transformation","symbol_family":"nature","primary_symbol":"flame process","query":"Wood visibly shrinks and disappears while the flame continues burning as the persistent process.","symbol_query":"Wood visibly shrinks and disappears while the flame continues burning as the persistent process.","symbolic_kind":"flame_process","symbolic_palette":"amber","start":151.762,"duration":9.105,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"We keep staring at the costume while reality keeps protecting the dance.","keywords":["costume","dance"],"kw_times":{"costume":160.867,"dance":162.882},"semantic_anchor":"A costume outline fades away while the dancer’s motion trail continues across the frame.","visual_function":"contrast","symbol_family":"identity","primary_symbol":"costume dance","query":"A costume outline fades away while the dancer’s motion trail continues across the frame.","symbol_query":"A costume outline fades away while the dancer’s motion trail continues across the frame.","symbolic_kind":"costume_dance","symbolic_palette":"red","start":160.867,"duration":4.459,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"Maybe death, change, identity, and time seem so confusing because we are asking what happens to the thing… when the deeper question is what happens to the pattern.","keywords":["thing","pattern"],"kw_times":{"thing":170.081,"pattern":174.813},"semantic_anchor":"A fixed solid cube labeled THING sits beside a living network labeled PATTERN that continuously reorganizes.","visual_function":"contrast","symbol_family":"geometry","primary_symbol":"thing vs pattern","query":"A fixed solid cube labeled THING sits beside a living network labeled PATTERN that continuously reorganizes.","symbol_query":"A fixed solid cube labeled THING sits beside a living network labeled PATTERN that continuously reorganizes.","symbolic_kind":"thing_vs_pattern","symbolic_palette":"violet","start":165.326,"duration":11.595,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false},{"text":"You may have spent your whole life trying to protect the instrument… without realizing reality has always been listening to the music.","keywords":["instrument","music"],"kw_times":{"instrument":178.936,"music":183.332},"semantic_anchor":"A protected instrument fades beneath expanding musical waves, ending with reality listening to the music rather than guarding the object.","visual_function":"perspective_shift","symbol_family":"object_tool","primary_symbol":"instrument final","query":"A protected instrument fades beneath expanding musical waves, ending with reality listening to the music rather than guarding the object.","symbol_query":"A protected instrument fades beneath expanding musical waves, ending with reality listening to the music rather than guarding the object.","symbolic_kind":"instrument_final","symbolic_palette":"cyan","start":176.921,"duration":8.81,"motion_kind":"video","motion_mode":"video","motion_source":"deterministic_symbolic","motion_verified":false}]}'''

def main(build_dir):
    bd=Path(build_dir); bd.mkdir(parents=True,exist_ok=True)
    script=json.loads(PAYLOAD)
    (bd/"script.json").write_text(json.dumps(script,indent=1,ensure_ascii=False),encoding="utf-8")
    (bd/"words.json").write_text("[]\n",encoding="utf-8")
    print(f"created {bd}/script.json with {len(script['scenes'])} audited scenes")

if __name__=="__main__":
    main(sys.argv[1] if len(sys.argv)>1 else "build/pattern-wearing-matter-v2")
